import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  FaPlusCircle,
  FaQuestionCircle,
  FaClipboardCheck,
  FaBookOpen
} from "react-icons/fa";
import AlertBox from "./AlertBox";

function QuizTeacher() {
  const teacherId = localStorage.getItem("user_id");

 onst [courseId, setCourseId] = useState("");
  const [quizId, setQuizId] = useState(null);
  const [alert, setAlert] = useState(null);

  const [quizForm, setQuizForm] = useState({
    course_id: "",
    title: ""
  });

  const [questionForm, setQuestionForm] = useState({
    question: "",
    option1: "",
    option2: "",
    option3: "",
    option4: "",
    correct_answer: ""
  });

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const res = await axios.get("http://127.0.0.1:8000/courses");
        const allCourses = res.data.courses || [];

        const myCourses = allCourses.filter(
          (course) => String(course.teacher_id) === String(teacherId)
        );

        setCourses(myCourses);
      } catch (error) {
        console.error(error);
      }
    };

    fetchCourses();
  }, [teacherId]);

  const handleQuizChange = (e) => {
    setQuizForm({
      ...quizForm,
      [e.target.name]: e.target.value
    });
  };

  const handleQuestionChange = (e) => {
    setQuestionForm({
      ...questionForm,
      [e.target.name]: e.target.value
    });
  };

  const handleCreateQuiz = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://127.0.0.1:8000/create-quiz", {
        course_id: parseInt(quizForm.course_id),
        teacher_id: parseInt(teacherId),
        title: quizForm.title
      });

      setQuizId(res.data.quiz_id);

      setAlert({
        message: "Quiz created successfully. Now add questions.",
        type: "success"
      });
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Quiz creation failed",
        type: "error"
      });
    }
  };

  const handleAddQuestion = async (e) => {
    e.preventDefault();

    if (!quizId) {
      setAlert({
        message: "Create quiz first",
        type: "error"
      });
      return;
    }

    try {
      await axios.post("http://127.0.0.1:8000/add-question", {
        quiz_id: quizId,
        ...questionForm
      });

      setAlert({
        message: "Question added successfully",
        type: "success"
      });

      setQuestionForm({
        question: "",
        option1: "",
        option2: "",
        option3: "",
        option4: "",
        correct_answer: ""
      });
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Failed to add question",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: "20px",
          marginBottom: "25px"
        }}
      >
        <div style={cardStyle("#ede7f6")}>
          <h3>My Courses</h3>
          <p style={numberStyle}>{courses.length}</p>
        </div>
        <div style={cardStyle("#e3f2fd")}>
          <h3>Quiz Status</h3>
          <p style={numberStyle}>{quizId ? "Created" : "Not Created"}</p>
        </div>
        <div style={cardStyle("#f3e5f5")}>
          <h3>Quiz Panel</h3>
          <p style={numberStyle}>
            <FaClipboardCheck />
          </p>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1.2fr",
          gap: "25px"
        }}
      >
        <div style={panelStyle}>
          <h3 style={headingStyle}>
            <FaBookOpen />
            Create Quiz
          </h3>

          <form
            onSubmit={handleCreateQuiz}
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "14px"
            }}
          >
            <select
              name="course_id"
              value={quizForm.course_id}
              onChange={handleQuizChange}
              style={inputStyle}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title}
                </option>
              ))}
            </select>

            <input
              type="text"
              name="title"
              placeholder="Quiz Title"
              value={quizForm.title}
              onChange={handleQuizChange}
              style={inputStyle}
            />

            <button type="submit" style={primaryBtn}>
              <FaPlusCircle />
              Create Quiz
            </button>
          </form>
        </div>

        <div style={panelStyle}>
          <h3 style={headingStyle}>
            <FaQuestionCircle />
            Add Questions
          </h3>

          {!quizId && (
            <p style={{ color: "#d32f2f", marginBottom: "15px" }}>
              First create a quiz, then add questions.
            </p>
          )}

          <form
            onSubmit={handleAddQuestion}
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "12px"
            }}
          >
            <textarea
              name="question"
              placeholder="Enter question"
              value={questionForm.question}
              onChange={handleQuestionChange}
              rows="3"
              style={inputStyle}
            />

            <input
              type="text"
              name="option1"
              placeholder="Option 1"
              value={questionForm.option1}
              onChange={handleQuestionChange}
              style={inputStyle}
            />

            <input
              type="text"
              name="option2"
              placeholder="Option 2"
              value={questionForm.option2}
              onChange={handleQuestionChange}
              style={inputStyle}
            />

            <input
              type="text"
              name="option3"
              placeholder="Option 3"
              value={questionForm.option3}
              onChange={handleQuestionChange}
              style={inputStyle}
            />

            <input
              type="text"
              name="option4"
              placeholder="Option 4"
              value={questionForm.option4}
              onChange={handleQuestionChange}
              style={inputStyle}
            />

            <select
              name="correct_answer"
              value={questionForm.correct_answer}
              onChange={handleQuestionChange}
              style={inputStyle}
            >
              <option value="">Select Correct Answer</option>
              <option value={questionForm.option1}>{questionForm.option1 || "Option 1"}</option>
              <option value={questionForm.option2}>{questionForm.option2 || "Option 2"}</option>
              <option value={questionForm.option3}>{questionForm.option3 || "Option 3"}</option>
              <option value={questionForm.option4}>{questionForm.option4 || "Option 4"}</option>
            </select>

            <button type="submit" style={primaryBtn}>
              <FaPlusCircle />
              Add Question
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

const cardStyle = (bg) => ({
  background: bg,
  borderRadius: "16px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.06)"
});

const numberStyle = {
  fontSize: "24px",
  fontWeight: "bold",
  color: "#4a148c"
};

const panelStyle = {
  background: "#fff",
  borderRadius: "18px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const headingStyle = {
  display: "flex",
  alignItems: "center",
  gap: "10px",
  color: "#6a1b9a",
  marginBottom: "18px"
};

const inputStyle = {
  padding: "12px",
  borderRadius: "10px",
  border: "1px solid #ccc",
  outline: "none",
  width: "100%",
  boxSizing: "border-box"
};

const primaryBtn = {
  background: "#7b1fa2",
  color: "white",
  border: "none",
  padding: "12px",
  borderRadius: "10px",
  fontWeight: "bold",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  gap: "8px"
};

export default QuizTeacher;
